const items = $input.all();

if (items.length === 0) {
  throw new Error("No English questions were found.");
}

// Pick one random question
const row = items[Math.floor(Math.random() * items.length)].json;

// Function to find a column regardless of capitalization or spacing
function getField(data, possibleNames) {
  const keys = Object.keys(data);

  const normalizedKeys = {};
  for (const key of keys) {
    normalizedKeys[key.trim().toUpperCase().replace(/[_-]/g, " ")] = key;
  }

  for (const name of possibleNames) {
    const normalized = name.toUpperCase().replace(/[_-]/g, " ");
    if (normalizedKeys[normalized]) {
      return data[normalizedKeys[normalized]];
    }
  }

  return undefined;
}

const question = getField(row, [
  "QUESTION",
  "QUESTIONS"
]);

const optionA = getField(row, [
  "A",
  "OPTION A",
  "OPTIONA",
  "CHOICE A"
]);

const optionB = getField(row, [
  "B",
  "OPTION B",
  "OPTIONB",
  "CHOICE B"
]);

const optionC = getField(row, [
  "C",
  "OPTION C",
  "OPTIONC",
  "CHOICE C"
]);

const optionD = getField(row, [
  "D",
  "OPTION D",
  "OPTIOND",
  "CHOICE D"
]);

const answer = getField(row, [
  "ANSWER",
  "CORRECT ANSWER",
  "CORRECT OPTION"
]);

return [
  {
    json: {
      subject: "English",
      question,
      optionA,
      optionB,
      optionC,
      optionD,
      answer
    }
  }
];

